/**
 * A Redux-style store with:
 *  - applyMiddleware-style middleware (composed right-to-left, first listed = outermost)
 *  - notifications batched per outermost dispatch (nested synchronous dispatches
 *    from middleware cause exactly one subscriber flush)
 *  - a guard that throws if a reducer dispatches
 *  - a built-in devtools recorder: every dispatched action + resulting state is
 *    captured; `jumpTo(index)` rewinds `getState()` to a historical state and
 *    pauses recording; `resume()` returns to the present.
 */

export interface Action<T extends string = string> {
  type: T;
  [extra: string]: any;
}

/** Dispatch accepts plain actions; middleware may widen it (e.g. thunks). */
export type Dispatcher<S, A extends Action> = (action: A | Function) => any;

export interface MiddlewareAPI<S, A extends Action> {
  getState(): S;
  dispatch: Dispatcher<S, A>;
}

export type Middleware<S, A extends Action = Action> = (
  api: MiddlewareAPI<S, A>
) => (next: Dispatcher<S, A>) => Dispatcher<S, A>;

export type Reducer<S, A extends Action = Action> = (
  state: S | undefined,
  action: A
) => S;

export interface HistoryEntry<S, A extends Action> {
  readonly action: A;
  readonly state: S;
}

export interface Store<S, A extends Action> {
  getState(): S;
  dispatch: Dispatcher<S, A>;
  subscribe(listener: () => void): () => void;
  /** Rewind the view to `history[index]`. Pauses recording until resume(). */
  jumpTo(index: number): void;
  /** Leave time travel; getState() returns the live present again. */
  resume(): void;
  /** Snapshot of every (action, resulting state) pair, oldest first. */
  getHistory(): ReadonlyArray<HistoryEntry<S, A>>;
}

const INIT_ACTION = { type: '@@store/INIT' } as Action;

function compose(...fns: Array<(arg: any) => any>): (arg: any) => any {
  if (fns.length === 0) return (x) => x;
  if (fns.length === 1) return fns[0];
  // Right-to-left: compose(f, g)(x) === f(g(x)).
  return fns.reduce((a, b) => (...args: any[]) => a(b(...args)));
}

export function createStore<S, A extends Action = Action>(
  reducer: Reducer<S, A>,
  preloadedState?: S,
  middlewares: ReadonlyArray<Middleware<S, A>> = []
): Store<S, A> {
  let present: S = preloadedState !== undefined
    ? preloadedState
    : reducer(undefined, INIT_ACTION as A);

  // --- devtools recorder -------------------------------------------------
  const history: Array<HistoryEntry<S, A>> = [];
  let viewIndex = -1; // valid while jumped
  let jumped = false; // recording paused; getState() serves the historical view
  let previewState: S | undefined; // result of dispatching while jumped

  // --- listener bookkeeping (Redux-style double buffer) -------------------
  type Listener = () => void;
  let currentListeners: Listener[] = [];
  let nextListeners: Listener[] = currentListeners;

  function ensureCanMutateNextListeners(): void {
    if (nextListeners === currentListeners) {
      nextListeners = currentListeners.slice();
    }
  }

  // --- notification batching ----------------------------------------------
  let dispatchDepth = 0; // > 0 while inside the outermost dispatch call
  let pendingNotify = false; // a state change happened; flush when unwound
  let reducing = false; // true while a reducer is executing (dispatch guard)

  function flushListeners(): void {
    currentListeners = nextListeners;
    for (const listener of currentListeners) {
      // Skip listeners that were unsubscribed earlier during this same flush.
      if (nextListeners.indexOf(listener) !== -1) listener();
    }
  }

  function requestNotify(): void {
    if (dispatchDepth > 0) {
      pendingNotify = true; // wait for the outermost dispatch to unwind
    } else {
      flushListeners();
    }
  }

  // --- base dispatch -------------------------------------------------------
  function baseDispatch(action: A): A {
    if (typeof action !== 'object' || action === null) {
      throw new Error('Actions must be plain objects.');
    }
    if (typeof (action as any).type === 'undefined') {
      throw new Error('Actions may not have an undefined "type" property.');
    }
    if (reducing) {
      throw new Error('Reducers may not dispatch actions.');
    }

    const input = jumped ? effectiveState() : present;
    reducing = true;
    let nextState: S;
    try {
      nextState = reducer(input, action);
    } finally {
      reducing = false;
    }

    if (!jumped) {
      // Live mode: commit and record.
      present = nextState;
      history.push({ action, state: nextState });
    } else {
      // Time-travelling: recording is paused; the result only updates the
      // preview so the present stays untouched until resume().
      previewState = nextState;
    }

    requestNotify();
    return action;
  }

  function effectiveState(): S {
    if (!jumped) return present;
    return previewState !== undefined ? previewState : history[viewIndex].state;
  }

  // --- middleware wiring ---------------------------------------------------
  const api: MiddlewareAPI<S, A> = {
    getState: () => effectiveState(),
    dispatch: (action: any) => dispatch(action),
  };

  const chainedDispatch = compose(
    ...middlewares.map((mw) => mw(api))
  )(baseDispatch as Dispatcher<S, A>) as Dispatcher<S, A>;

  // --- public dispatch: wraps the whole chain so nested synchronous
  // dispatches from middleware share a single subscriber notification ------
  function dispatch(action: any): any {
    if (reducing) {
      throw new Error('Reducers may not dispatch actions.');
    }
    dispatchDepth++;
    try {
      return chainedDispatch(action);
    } finally {
      dispatchDepth--;
      if (dispatchDepth === 0 && pendingNotify) {
        pendingNotify = false;
        flushListeners();
      }
    }
  }

  // --- public API -----------------------------------------------------------
  function getState(): S {
    return effectiveState();
  }

  function subscribe(listener: Listener): () => void {
    if (typeof listener !== 'function') {
      throw new Error('Expected the listener to be a function.');
    }
    ensureCanMutateNextListeners();
    nextListeners.push(listener);
    return function unsubscribe() {
      ensureCanMutateNextListeners();
      const index = nextListeners.indexOf(listener);
      if (index !== -1) nextListeners.splice(index, 1);
    };
  }

  function jumpTo(index: number): void {
    if (!Number.isInteger(index) || index < 0 || index >= history.length) {
      throw new Error(
        `jumpTo(index): index ${index} is out of bounds [0, ${history.length - 1}].`
      );
    }
    viewIndex = index;
    jumped = true;
    previewState = undefined;
    flushListeners();
  }

  function resume(): void {
    if (!jumped) return;
    jumped = false;
    viewIndex = -1;
    previewState = undefined;
    flushListeners();
  }

  function getHistory(): ReadonlyArray<HistoryEntry<S, A>> {
    return history.slice();
  }

  return { getState, dispatch, subscribe, jumpTo, resume, getHistory };
}

