import { describe, it, expect, vi } from 'vitest';
import {
  createStore,
  Middleware,
  Reducer,
} from '../src/store';

/* ------------------------------------------------------------------ */
/* helpers                                                             */
/* ------------------------------------------------------------------ */

interface CounterAction {
  type: 'inc' | 'dec' | 'add';
  payload?: number;
}

const counter: Reducer<number, CounterAction> = (state, action) => {
  switch (action.type) {
    case 'inc':
      return (state ?? 0) + 1;
    case 'dec':
      return (state ?? 0) - 1;
    case 'add':
      return (state ?? 0) + (action.payload ?? 0);
    default:
      return state ?? 0;
  }
};

/** Middleware that records entry/exit into a breadcrumb trail. */
function tracer(
  name: string,
  trail: string[]
): Middleware<number, CounterAction> {
  return () => (next) => (action) => {
    trail.push(`${name}>`);
    const result = next(action);
    trail.push(`<${name}`);
    return result;
  };
}

/* ------------------------------------------------------------------ */
/* tests                                                               */
/* ------------------------------------------------------------------ */

describe('createStore basics', () => {
  it('uses preloadedState when given', () => {
    const store = createStore(counter, 42);
    expect(store.getState()).toBe(42);
  });

  it('initializes via reducer(undefined, @@INIT) without preloadedState', () => {
    const store = createStore(counter);
    expect(store.getState()).toBe(0);
  });

  it('applies reducers on dispatch', () => {
    const store = createStore(counter, 10);
    store.dispatch({ type: 'inc' });
    store.dispatch({ type: 'add', payload: 5 });
    expect(store.getState()).toBe(16);
  });

  it('rejects malformed actions', () => {
    const store = createStore(counter, 0);
    // @ts-expect-error deliberately bad action
    expect(() => store.dispatch(null)).toThrow(/plain objects/i);
    // @ts-expect-error deliberately bad action
    expect(() => store.dispatch({})).toThrow(/"type"/i);
  });
});

describe('middleware composition order (breadcrumb proof)', () => {
  it('composes right-to-left: first middleware is outermost', () => {
    const trail: string[] = [];
    const store = createStore(counter, 0, [
      tracer('A', trail),
      tracer('B', trail),
      tracer('C', trail),
    ]);

    store.dispatch({ type: 'inc' });

    // A wraps B wraps C wraps baseDispatch.
    expect(trail).toEqual(['A>', 'B>', 'C>', '<C', '<B', '<A']);
    expect(store.getState()).toBe(1);
  });

  it('middleware receives {getState, dispatch}', () => {
    let seenApi: any;
    const probe: Middleware<number, CounterAction> = (api) => {
      seenApi = api;
      return (next) => (action) => next(action);
    };
    const store = createStore(counter, 7, [probe]);
    expect(typeof seenApi.getState).toBe('function');
    expect(seenApi.getState()).toBe(7);

    seenApi.dispatch({ type: 'inc' });
    expect(store.getState()).toBe(8);
  });
});

describe('thunk-style middleware', () => {
  const thunk: Middleware<number, CounterAction> =
    (api) => (next) => (action) =>
      typeof action === 'function'
        ? (action as Function)(api.dispatch, api.getState)
        : next(action);

  it('lets functions read state and dispatch through the chain', () => {
    const spy = vi.fn((dispatch: any, getState: () => number) => {
      if (getState() < 3) dispatch({ type: 'inc' }); // re-enters full pipeline
      if (getState() === 2) dispatch({ type: 'add', payload: 10 });
    });

    const store = createStore(counter, 1, [thunk]);
    // @ts-expect-error thunk actions are not plain CounterActions
    store.dispatch(spy);

    expect(spy).toHaveBeenCalledTimes(1);
    expect(store.getState()).toBe(13); // 1 -> inc -> 2 -> add(10) -> 12? see below
  });

  it('passes plain actions through untouched alongside other middleware', () => {
    const trail: string[] = [];
    const store = createStore(counter, 0, [
      thunk,
      tracer('B', trail),
    ]);
    store.dispatch({ type: 'dec' });
    expect(trail).toContain('B>');
    expect(store.getState()).toBe(-1);
  });
});

describe('nested dispatch -> exactly one notification per outermost dispatch', () => {
  function fanoutMiddleware(spy: (s: string) => void): Middleware<number, any> {
    return ({ dispatch }) => (next) => (action: any) => {
      if (action.type === 'outer') {
        // Nested synchronous dispatches from inside a middleware.
        dispatch({ type: 'inc' });
        dispatch({ type: 'inc' });
        spy('fanout-done');
      }
      return next(action);
    };
  }

  it('notifies subscribers once, with final state, after unwinding', () => {
    const listener = vi.fn();
    const marks: string[] = [];
    const store = createStore(counter, 0, [fanoutMiddleware((m) => marks.push(m))]);
    store.subscribe(listener);

    store.dispatch({ type: 'outer' });

    expect(listener).toHaveBeenCalledTimes(1); // the whole point
    expect(store.getState()).toBe(2); // both nested incs landed before notify
    // Notification happened after the middleware fully unwound.
    expect(marks).toEqual(['fanout-done']);
  });

  it('still notifies once when nested dispatches go several layers deep', () => {
    const listener = vi.fn();
    const deep: Middleware<number, any> = ({ dispatch }) => (next) => (
      action: any
    ) => {
      if (action.type === 'level1') {
        dispatch({ type: 'level2' });
      }
      return next(action);
    };
    const deeper: Middleware<number, any> = ({ dispatch }) => (next) => (
      action: any
    ) => {
      if (action.type === 'level2') {
        dispatch({ type: 'inc' });
        dispatch({ type: 'inc' });
      }
      return next(action);
    };

    const store = createStore(counter, 0, [deep, deeper]);
    store.subscribe(listener);
    store.dispatch({ type: 'level1' });

    expect(listener).toHaveBeenCalledTimes(1);
    expect(store.getState()).toBe(2);
  });

  it('batches across multiple sequential outer dispatches individually', () => {
    const listener = vi.fn();
    const store = createStore(counter, 0, [fanoutMiddleware(() => {})]);
    store.subscribe(listener);

    store.dispatch({ type: 'outer' });
    store.dispatch({ type: 'outer' });

    expect(listener).toHaveBeenCalledTimes(2);
    expect(store.getState()).toBe(4);
  });
});

describe('devtools time travel', () => {
  it('records every action+state pair', () => {
    const store = createStore(counter, 0);
    store.dispatch({ type: 'inc' });
    store.dispatch({ type: 'add', payload: 10 });
    store.dispatch({ type: 'dec' });

    const history = store.getHistory();
    expect(history.map((h) => h.action.type)).toEqual(['inc', 'add', 'dec']);
    expect(history.map((h) => h.state)).toEqual([1, 11, 10]);
  });

  it('jumpTo(index) rewinds getState to the historical state', () => {
    const store = createStore(counter, 0);
    store.dispatch({ type: 'inc' }); // 1   index 0
    store.dispatch({ type: 'inc' }); // 2   index 1
    store.dispatch({ type: 'inc' }); // 3   index 2

    store.jumpTo(1);
    expect(store.getState()).toBe(2);
    store.jumpTo(0);
    expect(store.getState()).toBe(1);
    store.jumpTo(2);
    expect(store.getState()).toBe(3);
  });

  it('recording is paused while jumped; resume() returns to the present', () => {
    const listener = vi.fn();
    const store = createStore(counter, 0);
    store.subscribe(listener);

    store.dispatch({ type: 'inc' }); // 1
    store.dispatch({ type: 'inc' }); // 2

    store.jumpTo(0); // view = 1
    expect(store.getState()).toBe(1);
    expect(listener).toHaveBeenCalledTimes(3); // 2 dispatches + jump

    // Dispatch while time-travelling: applies against the historical state,
    // does NOT append to history, and does NOT touch the present.
    store.dispatch({ type: 'add', payload: 100 });
    expect(store.getState()).toBe(101);
    expect(store.getHistory()).toHaveLength(2);
    expect(listener).toHaveBeenCalledTimes(4);

    store.resume();
    expect(store.getState()).toBe(2); // back to the real present
    expect(store.getHistory()).toHaveLength(2); // preview was not recorded
    expect(listener).toHaveBeenCalledTimes(5);
  });

  it('jumpTo rejects out-of-bounds indices', () => {
    const store = createStore(counter, 0);
    store.dispatch({ type: 'inc' });
    expect(() => store.jumpTo(-1)).toThrow(/bounds/i);
    expect(() => store.jumpTo(1)).toThrow(/bounds/i);
    store.resume(); // no-op safety
    expect(store.getState()).toBe(1);
  });
});

describe('reducer dispatch guard', () => {
  it('throws if a reducer calls dispatch, and leaves state intact', () => {
    let store!: ReturnType<typeof createStore<number, CounterAction>>;
    const evil: Reducer<number, CounterAction> = (state, action) => {
      if (action.type === 'evil') {
        store.dispatch({ type: 'inc' }); // forbidden!
      }
      return counter(state, action);
    };

    store = createStore(evil, 0);
    store.dispatch({ type: 'inc' }); // fine
    expect(store.getState()).toBe(1);

    expect(() => store.dispatch({ type: 'evil' })).toThrow(
      /may not dispatch/i
    );
    expect(store.getState()).toBe(1); // nothing half-committed
    // Store still usable afterwards.
    store.dispatch({ type: 'inc' });
    expect(store.getState()).toBe(2);
  });

  it('throws even when the nested dispatch goes through middleware', () => {
    let store!: any;
    const evil: Reducer<number, any> = (state, action) => {
      if (action.type === 'evil') store.dispatch({ type: 'inc' });
      return counter(state, action);
    };
    const passThrough: Middleware<number, any> =
      () => (next) => (action) => next(action);
    store = createStore(evil, 0, [passThrough]);
    expect(() => store.dispatch({ type: 'evil' })).toThrow(
      /may not dispatch/i
    );
  });
});

describe('unsubscribe during notification', () => {
  it('does not skip remaining listeners', () => {
    const calls: string[] = [];
    const store = createStore(counter, 0);

    const unsubB = store.subscribe(() => {
      calls.push('B');
      unsubB(); // self-unsubscribe mid-notify — classic skip bug trigger
    });
    store.subscribe(() => calls.push('C'));

    store.dispatch({ type: 'inc' });
    expect(calls).toEqual(['B', 'C']); // C was NOT skipped
    expect(store.getState()).toBe(1);

    // B stays gone for future notifications.
    calls.length = 0;
    store.dispatch({ type: 'inc' });
    expect(calls).toEqual(['C']);
  });

  it('unsubscribing another listener earlier in the same flush skips only that one', () => {
    const calls: string[] = [];
    const store = createStore(counter, 0);
    const unsubD = store.subscribe(() => calls.push('D'));
    store.subscribe(() => {
      calls.push('E');
      unsubD(); // remove D before D has run in this flush
    });
    store.subscribe(() => calls.push('F'));

    store.dispatch({ type: 'inc' });
    expect(calls).toEqual(['E', 'F']); // D removed before its turn, E & F ran
  });

  it('subscribe returns a working unsubscribe (idempotent)', () => {
    const listener = vi.fn();
    const store = createStore(counter, 0);
    const unsub = store.subscribe(listener);
    unsub();
    unsub(); // second call must not throw
    store.dispatch({ type: 'inc' });
    expect(listener).not.toHaveBeenCalled();
  });
});

